function factorial(n){ n=Math.floor(n); if(n<0) return NaN; var r=1; for(var i=2;i<=n;i++) r*=i; return r; }
function perm(n,k){ n=Math.floor(n); k=Math.floor(k); if(k<0||k>n) return 0; var r=1; for(var i=n-k+1;i<=n;i++) r*=i; return r; }
function comb(n,k){ n=Math.floor(n); k=Math.floor(k); if(k<0||k>n) return 0; if(k>n-k) k=n-k; var r=1; for(var i=1;i<=k;i++){ r=r*(n-k+i)/i; } return Math.round(r); }
function binomP(n,k,p){ if(p<0||p>1) return NaN; return comb(n,k)*Math.pow(p,k)*Math.pow(1-p,n-k); }
function binomAtLeast(n,k,p){ var s=0; for(var i=k;i<=n;i++) s+=binomP(n,i,p); return s; }
function binomAtMost(n,k,p){ var s=0; for(var i=0;i<=k;i++) s+=binomP(n,i,p); return s; }
var EXPORTS={ factorial:factorial, perm:perm, comb:comb, binomP:binomP, binomAtLeast:binomAtLeast, binomAtMost:binomAtMost };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ProbabilityForgePure = EXPORTS; }
